<script setup>
import {computed,ref,watch} from 'vue'
import {tourExamples,twoOptSteps} from '../services/local-search.mjs'
import SimulationControls from './SimulationControls.vue'
import SearchTraceCode from './SearchTraceCode.vue'
const preset=ref('cross'),problem=ref(tourExamples.cross),step=ref(0),input=ref(JSON.stringify({points:problem.value.points,tour:problem.value.tour},null,2)),error=ref('')
const trace=computed(()=>Array.from(twoOptSteps(problem.value))),state=computed(()=>trace.value[Math.min(step.value,trace.value.length-1)]),key=computed(()=>JSON.stringify(problem.value))
watch(key,()=>step.value=0);watch(preset,()=>{problem.value=tourExamples[preset.value];input.value=JSON.stringify({points:problem.value.points,tour:problem.value.tour},null,2);error.value=''})
const points=computed(()=>{const xs=problem.value.points.map(p=>p[0]),ys=problem.value.points.map(p=>p[1]),loX=Math.min(...xs),loY=Math.min(...ys),span=Math.max(Math.max(...xs)-loX,Math.max(...ys)-loY,1);return problem.value.points.map(p=>[45+300*(p[0]-loX)/span,280-220*(p[1]-loY)/span])})
const edges=computed(()=>state.value.tour.map((v,i)=>({a:points.value[v],b:points.value[state.value.tour[(i+1)%state.value.tour.length]],changed:i===state.value.i||i===state.value.j})))
const proposals=computed(()=>{const s=state.value;if(s.phase!=='candidate')return [];const t=s.tour;return [[t[s.i],t[s.j]],[t[(s.i+1)%t.length],t[(s.j+1)%t.length]]].map(([a,b])=>({a:points.value[a],b:points.value[b]}))})
function apply(){try{const p=JSON.parse(input.value);Array.from(twoOptSteps(p));problem.value=p;error.value=''}catch(e){error.value=e.message}}
</script>
<template><section class="math-lab tsp-two-opt" aria-label="Mô phỏng phép đổi 2-opt"><label>Bài toán<select v-model="preset"><option v-for="(p,id) in tourExamples" :key="id" :value="id">{{ p.title }}</option></select></label><SimulationControls v-model="step" :max="trace.length-1" :reset-key="key"/><svg viewBox="0 0 400 325" role="img" aria-label="Chu trình hiện tại và hai cạnh được thay thế"><line v-for="(e,i) in edges" :key="i" :x1="e.a[0]" :y1="e.a[1]" :x2="e.b[0]" :y2="e.b[1]" :class="{removed:e.changed&&state.phase==='candidate'}"/><line v-for="(e,i) in proposals" :key="'p'+i" :x1="e.a[0]" :y1="e.a[1]" :x2="e.b[0]" :y2="e.b[1]" class="proposed"/><g v-for="(p,i) in points" :key="i"><circle :cx="p[0]" :cy="p[1]" r="6"/><text :x="p[0]" :y="p[1]-12" text-anchor="middle">{{ String.fromCharCode(65+i) }}</text></g></svg><p class="tsp-status" role="status">Chiều dài hiện tại {{ state.cost.toFixed(3) }}. <template v-if="state.phase==='candidate'">Thử đảo đoạn: Δ = {{ state.delta.toFixed(3) }}. Nét đứt là cạnh bỏ, nét xanh là cạnh thêm.</template><template v-else-if="state.phase==='local'">Không còn bước 2-opt cải thiện. Đây là tối ưu cục bộ, chưa phải chứng nhận tối ưu toàn cục.</template><template v-else-if="state.phase==='move'">Nhận bước cải thiện rồi quét lại từ đầu.</template><template v-else>Chu trình khép kín đi qua mỗi thành phố đúng một lần.</template></p><p>Thứ tự hiện tại: {{ state.tour.map(i=>String.fromCharCode(65+i)).join(' → ') }} → {{ String.fromCharCode(65+state.tour[0]) }}.</p><details><summary>Tự nhập tọa độ và thứ tự</summary><p>points là tọa độ Euclid. tour là hoán vị chỉ số từ 0. Bộ xem dùng khoảng cách đối xứng và nhận bước cải thiện đầu tiên, với sai số số thực 10⁻¹⁰.</p><label>Dữ liệu JSON<textarea v-model="input" rows="8" spellcheck="false"/></label><button type="button" @click="apply">Dùng dữ liệu</button><p v-if="error" role="alert">{{ error }}</p></details><SearchTraceCode name="twoOptSteps" :phase="state.phase"/></section></template>
<style scoped>
.tsp-two-opt{min-width:0}.tsp-two-opt label{display:grid;gap:6px;font:var(--fs-small)/1.7 var(--font-ui)}.tsp-two-opt :is(select,textarea,button){min-height:44px;min-width:0;max-width:100%;padding:8px;background:var(--paper);color:var(--ink);border:1px solid var(--control);border-radius:var(--radius);font:inherit}.tsp-two-opt textarea{width:100%;font:13px/1.7 var(--font-code)}svg{display:block;width:100%;max-width:520px;margin:12px auto;background:var(--paper)}svg line{stroke:var(--ink-2);stroke-width:1.5;vector-effect:non-scaling-stroke}svg line.removed{stroke:var(--do);stroke-dasharray:5 4}svg line.proposed{stroke:var(--xanh);stroke-width:2}svg circle{fill:var(--tim);stroke:var(--paper);stroke-width:2}svg text{fill:var(--ink);font:18px var(--font-ui)}.tsp-status{background:var(--tim-soft);border-left:3px solid var(--tim);padding:12px}summary{min-height:44px;cursor:pointer}:is(select,textarea,button,summary):focus-visible{outline:3px solid var(--tim);outline-offset:3px}
</style>
